// Build a single structured log line + a human alert from the error payload.
const e = $input.first().json;
const execution = e.execution || {};
const error = execution.error || {};
const record = {
  ts: new Date().toISOString(),
  level: 'error',
  msg: 'unhandled workflow error (dead-letter)',
  workflow: (e.workflow && e.workflow.name) || 'unknown',
  executionId: execution.id,
  lastNode: execution.lastNodeExecuted,
  errorMessage: error.message,
};
console.log(JSON.stringify(record));
return [{ json: record }];

